+        if (flags != 0) {
+            read_inputs(/*extended=*/true);
+            read_outputs();
+        }
+    } else {
+        /* We read a non-empty vin. Assume a normal vout follows. */
+        read_outputs();
+    }
+    if ((flags & 1) && fAllowWitness) {
